    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
for k in ['Demo pair 1','Demo pair 2']:
    i=G[k+' input']; o=G[k+' output']
    H,W=len(i),len(i[0]); A=[r[:W] for r in o[:H]]
    # brute force: does there exist dy,dx (mod H/W) such that A[r][c]==i[(r-dy)%H][(c-dx)%W]? and variants with flips
    found=None
    for dy in range(H):
        for dx in range(W):
            for fh in (0,1):
                for fv in (0,1):
                    Y=[[i[(r-dy)%H][(c-dx)%W] for c in range(W)] for r in range(H)]
                    if fh: Y=[row[::-1] for row in Y]
                    if fv: Y=Y[::-1]
                    if Y==A: found=('shift',dy,dx,fh,fv); break
                if found: break
            if found: break
        if found: break
    print(k, found)
